/** @noSelfInFile */
// Stub of the reforged-ts library for eslint-plugin-reforged's fixtures. It
// declares only what the rules classify: the Handle base, Wrappers with
// creations, lookups and the members a rule names, the Init stages and the
// Timer statics. Extend it when a rule needs another member; keep the shapes
// of the real library (packages/reforged-ts/src).

/** The Handle base every Wrapper extends. */
export declare abstract class Handle<T extends handle> {
  readonly handle: T;
  protected constructor(handle: T);
  /** The handle id: differs between clients as a table key. */
  get id(): number;
  static fromHandle<C extends Handle<handle>>(
    this: { readonly prototype: C },
    handle: C["handle"] | undefined,
  ): C | undefined;
}

