/** The player Wrapper. */
export declare class MapPlayer extends Handle<player> {
  static fromIndex(index: number): MapPlayer | undefined;
  /**
   * The local player.
   * @async
   */
  static fromLocal(): MapPlayer;
  get id(): number;
  get name(): string;
  isLocal(): boolean;
  /**
   * Runs `fn` on the client whose local player is `player` only: the
   * sanctioned local branch (static, runtime spec #52).
   */
  static runLocal(player: MapPlayer, fn: () => void): void;
}

export declare class Timer extends Handle<timer> {
  static create(): Timer;
  /**
   * Runs `handler` once after `timeout` seconds on a Timer it destroys; not a
   * creation, and it returns nothing (as in reforged-ts).
   */
  static after(timeout: number, handler: () => void): void;
  static fromExpired(): Timer | undefined;
  start(timeout: number, periodic: boolean, handlerFunc: () => void): void;
  destroy(): void;
}

